/* ---------- الطلبات: «خبرني إذا جهز» + الطلب من المنيو ---------- */
// أعمدة ورقة الطلبات: 1 المعرّف، 2 الجوال، 3 الاسم، 4 رقم الطلب، 5 الحالة، 6 وقت الطلب، 7 وقت الجاهزية،
// 8 إشعارات مجدولة، 9 الأصناف، 10 المجموع، 11 ملاحظة، 12 الزبون أكّد الاستلام، 13 النقاط اللي انضافت
function orders_() {
  const ss = SpreadsheetApp.getActive();
  let s = ss.getSheetByName('الطلبات');
  if (!s) {
    s = sheet_('الطلبات', ['المعرّف', 'الجوال', 'الاسم', 'رقم الفاتورة', 'الحالة', 'وقت الطلب', 'وقت الجاهزية']);
    s.getRange('D:D').setNumberFormat('@');
  }
  if (!s.getRange(1, 9).getValue()) {
    s.getRange(1, 8, 1, 6).setValues([['إشعارات مجدولة', 'الأصناف', 'المجموع (ريال)', 'ملاحظة', 'الزبون أكّد', 'نقاط انضافت']]).setFontWeight('bold');
  }
  return s;
}
function memberByToken_(t) {
  t = String(t || '').replace(/[^a-f0-9]/g, '');
  if (t.length < 20) return null;
  const data = members_().getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][5] || '') === t && data[i][4]) return { phone: normPhone_(data[i][0]), name: String(data[i][1]) };
  }
  return null;
}
function orderRows_() {
  const sh = orders_();
  const last = sh.getLastRow();
  if (last < 2) return [];
  const data = sh.getRange(1, 1, last, 13).getValues();
  const out = [];
  for (let i = 1; i < data.length; i++) {
    const d = data[i];
    if (!d[0]) continue;
    out.push({ id: String(d[0]), phone: normPhone_(d[1]), name: String(d[2]), invoice: String(d[3]),
               status: String(d[4]), at: d[5] instanceof Date ? d[5].getTime() : 0,
               readyAt: d[6] instanceof Date ? d[6].getTime() : 0, row: i + 1,
               items: String(d[8] || ''), total: Number(d[9]) || 0, note: String(d[10] || ''),
               seen: !!d[11], online: !!d[8], awarded: Number(d[12]) || 0 });
  }
  return out;
}
function orderView_(o) {
  return o ? { id: o.id, invoice: o.invoice, status: o.status, items: o.items, total: o.total, note: o.note, online: o.online, payLink: o.online ? payLink_() : '' } : null;
}
// الزبون يكتب رقم فاتورته ويطلب ننبهه
function orderNotify(token, invoice) {
  const m = memberByToken_(token);
  if (!m) throw new Error('سجّل دخولك من جديد');
  invoice = String(invoice || '').replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).trim().slice(0, 12);
  if (!invoice) throw new Error('اكتب رقم الفاتورة');
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const sh = orders_();
    // طلب واحد ينتظر لكل زبون: القديم يتبدّل (طلبات المنيو ما تنلغي)
    orderRows_().filter(o => o.phone === m.phone && o.status === 'ينتظر' && !o.online).forEach(o => sh.getRange(o.row, 5).setValue('ملغي'));
    sh.appendRow([Utilities.getUuid().slice(0, 8), m.phone, m.name, invoice, 'ينتظر', new Date(), '']);
  } finally { lock.releaseLock(); }
  return orderStatus(token);
}
// حالة آخر طلب للزبون (خلال آخر 3 ساعات)
function orderStatus(token) {
  const m = memberByToken_(token);
  if (!m) return null;
  const since = Date.now() - 3 * 3600e3;
  const mine = orderRows_().filter(o => o.phone === m.phone && o.at > since && !o.seen &&
    (o.status === 'ينتظر' || o.status === 'جاهز' || (o.status === 'مرفوض' && o.online)));
  if (!mine.length) return null;
  return orderView_(mine[mine.length - 1]);
}
function orderReceived(token, id) {
  const m = memberByToken_(token);
  if (!m) return null;
  const o = orderRows_().find(x => x.id === String(id) && x.phone === m.phone);
  if (!o) return null;
  const sh = orders_();
  if (o.online) {
    // طلب المنيو يبقى عند الإدارة لين يعلّم «استلم» (عشان النقاط)، بس نخفيه عند الزبون
    sh.getRange(o.row, 12).setValue(new Date());
    if (o.status === 'ينتظر') sh.getRange(o.row, 5).setValue('ألغاه الزبون');
  } else {
    sh.getRange(o.row, 5).setValue('استلم');
  }
  cancelPush_(o.row);
  return null;
}
// للإدارة: الطلبات اللي تنتظر + الجاهزة (المنيو لين تستلم، والفواتير آخر 30 دقيقة)
function adminOrders(pin) {
  checkPin_(pin);
  const now = Date.now();
  return orderRows_().filter(o => (o.status === 'ينتظر' && now - o.at < 12 * 3600e3) ||
      (o.status === 'جاهز' && (o.online ? now - o.readyAt < 12 * 3600e3 : now - o.readyAt < 30 * 60e3)))
    .map(o => ({ id: o.id, phone: o.phone, name: o.name, invoice: o.invoice, status: o.status, at: o.at,
                 items: o.items, total: o.total, note: o.note, online: o.online, seen: o.seen,
                 pts: o.online ? Math.round(o.total * POINTS_PER_RIYAL) : 0 }))
    .sort((a, b) => a.at - b.at);
}
function adminOrderReady(pin, id) {
  checkPin_(pin);
  const o = orderRows_().find(x => x.id === String(id));
  if (!o) throw new Error('الطلب غير موجود');
  const sh = orders_();
  sh.getRange(o.row, 5).setValue('جاهز');
  sh.getRange(o.row, 7).setValue(new Date());
  const ids = pushReady_(o.phone, o.invoice);
  if (ids.length) sh.getRange(o.row, 8).setValue(ids.join(','));
  return adminOrders(pin);
}
// «استلم»: طلب المنيو تنضاف نقاطه تلقائياً حسب مجموعه
function adminOrderClear(pin, id) {
  checkPin_(pin);
  const o = orderRows_().find(x => x.id === String(id));
  if (!o) return adminOrders(pin);
  const sh = orders_();
  sh.getRange(o.row, 5).setValue('استلم');
  cancelPush_(o.row);
  if (o.online && !o.awarded) {
    const pts = Math.round(o.total * POINTS_PER_RIYAL);
    if (pts > 0 && findRow_(o.phone)) {
      sh.getRange(o.row, 13).setValue(pts);
      adminAdjust(pin, o.phone, pts, 'طلب من المنيو #' + o.invoice);
    }
  }
  return adminOrders(pin);
}
// إلغاء طلب من المنيو (مثلاً صنف خلص) — الزبون يشوف إنه انلغى
function adminOrderReject(pin, id) {
  checkPin_(pin);
  const o = orderRows_().find(x => x.id === String(id));
  if (o) {
    orders_().getRange(o.row, 5).setValue(o.online ? 'مرفوض' : 'ملغي');
    cancelPush_(o.row);
    if (o.online) pushTo_(o.phone, 'Rya coffee ☕', 'نعتذر، ما قدرنا نجهّز طلبك رقم ' + o.invoice + '. تواصل معنا عند الكاشير');
  }
  return adminOrders(pin);
}

/* ---------- المنيو والطلب منه ---------- */
// أعمدة ورقة المنيو: 1 المعرّف، 2 الصنف، 3 السعر، 4 القسم، 5 متاح، 6 الوصف
function menu_() {
  const ss = SpreadsheetApp.getActive();
  let s = ss.getSheetByName('المنيو');
  if (!s) s = sheet_('المنيو', ['المعرّف', 'الصنف', 'السعر (ريال)', 'القسم', 'متاح', 'الوصف']);
  return s;
}
function menuRows_() {
  const data = menu_().getDataRange().getValues();
  const out = [];
  for (let i = 1; i < data.length; i++) {
    const d = data[i];
    if (!d[0] || !d[1]) continue;
    out.push({ id: String(d[0]), name: String(d[1]), price: Number(d[2]) || 0, cat: String(d[3] || 'مشروبات'),
               on: d[4] === true || String(d[4]).toUpperCase() === 'TRUE', desc: String(d[5] || ''), row: i + 1 });
  }
  return out;
}
function orderingOpen_() { return PropertiesService.getScriptProperties().getProperty('ORDERING') !== 'off'; }
function payLink_() { return PropertiesService.getScriptProperties().getProperty('PAY_LINK') || ''; }
function getMenu() {
  return { open: orderingOpen_(), payLink: payLink_(),
           items: menuRows_().filter(x => x.on).map(x => ({ id: x.id, name: x.name, price: x.price, cat: x.cat, desc: x.desc })) };
}
function nextOnlineNo_() {
  const p = PropertiesService.getScriptProperties();
  const key = 'ONO_' + today_();
  const n = Number(p.getProperty(key) || 0) + 1;
  p.setProperty(key, String(n));
  return 'W' + n;
}
// الزبون يرسل طلبه من المنيو (يدفع عند الاستلام)
function placeOrder(token, items, note) {
  const m = memberByToken_(token);
  if (!m) throw new Error('سجّل دخولك من جديد');
  if (!orderingOpen_()) throw new Error('الطلب من الصفحة موقوف الحين، اطلب من الكاشير');
  const menu = {};
  menuRows_().filter(x => x.on).forEach(x => { menu[x.id] = x; });
  const lines = [];
  let total = 0, count = 0;
  (Array.isArray(items) ? items : []).forEach(it => {
    const x = menu[String(it && it.id)];
    const q = Math.min(10, Math.max(0, Math.floor(Number(it && it.qty) || 0)));
    if (!x || !q) return;
    lines.push(q + '× ' + x.name);
    total += q * x.price; count += q;
  });
  if (!lines.length) throw new Error('اختر صنف واحد على الأقل');
  if (count > 20) throw new Error('الحد 20 صنف في الطلب الواحد');
  note = String(note || '').trim().slice(0, 140);
  total = Math.round(total * 100) / 100;
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    if (orderRows_().some(o => o.phone === m.phone && o.online && o.status === 'ينتظر' && Date.now() - o.at < 3 * 3600e3)) {
      throw new Error('عندك طلب ينتظر التجهيز، استنّاه يجهز أول');
    }
    orders_().appendRow([Utilities.getUuid().slice(0, 8), m.phone, m.name, nextOnlineNo_(), 'ينتظر', new Date(), '', '', lines.join('، '), total, note, '', '']);
  } finally { lock.releaseLock(); }
  return orderStatus(token);
}
/* المنيو (للإدارة) */
function adminListMenu(pin) {
  checkPin_(pin);
  return { open: orderingOpen_(), payLink: payLink_(),
           items: menuRows_().map(x => ({ id: x.id, name: x.name, price: x.price, cat: x.cat, on: x.on, desc: x.desc })) };
}
function adminAddMenuItem(pin, name, price, cat, desc) {
  checkPin_(pin);
  name = String(name || '').trim().slice(0, 50);
  cat = String(cat || '').trim().slice(0, 30) || 'مشروبات';
  desc = String(desc || '').trim().slice(0, 100);
  price = Math.round(Number(String(price || '').replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))) * 100) / 100;
  if (name.length < 2) throw new Error('اكتب اسم الصنف');
  if (!(price > 0)) throw new Error('اكتب السعر بالريال');
  menu_().appendRow([Utilities.getUuid().slice(0, 8), name, price, cat, true, desc]);
  return adminListMenu(pin);
}
function adminToggleMenuItem(pin, id, on) {
  checkPin_(pin);
  const x = menuRows_().find(r => r.id === String(id));
  if (!x) throw new Error('الصنف غير موجود');
  menu_().getRange(x.row, 5).setValue(!!on);
  return adminListMenu(pin);
}
function adminDeleteMenuItem(pin, id) {
  checkPin_(pin);
  const x = menuRows_().find(r => r.id === String(id));
  if (x) {
    const sh = menu_();
    if (sh.getLastRow() <= 2) sh.getRange(x.row, 1, 1, 6).clearContent(); else sh.deleteRow(x.row);
  }
  return adminListMenu(pin);
}
function adminSetOrdering(pin, open) {
  checkPin_(pin);
  PropertiesService.getScriptProperties().setProperty('ORDERING', open ? 'on' : 'off');
  return adminListMenu(pin);
}
function adminSetPayLink(pin, link) {
  checkPin_(pin);
  link = String(link || '').trim();
  if (link && !/^https:\/\/\S+$/i.test(link)) throw new Error('الرابط لازم يبدأ بـ https://');
  PropertiesService.getScriptProperties().setProperty('PAY_LINK', link.slice(0, 300));
  return adminListMenu(pin);
}
